fn sequence(name: &str) -> &'static [u8] {
    SEQUENCES
        .iter()
        .find(|(known, _)| *known == name)
        .map(|(_, letters)| letters.as_bytes())
        .expect("a probe sequence")
}

/// A probe's sequences as the report shows them: `-subject` labels `Query_N` and `Subject_N`.
struct Probe {
    query: &'static [u8],
    query_label: String,
    subjects: Vec<(&'static [u8], String)>,
    query_masks: Vec<(u32, u32)>,
    subject_masks: Vec<Vec<(u32, u32)>>,
}

impl Sequences for Probe {
    fn letters(&self, seq: SeqKey, from: u32, to: u32, out: &mut Vec<u8>) {
        let letters = match seq {
            SeqKey::Query => self.query,
            SeqKey::Subject(index) => self.subjects[index as usize].0,
        };
        out.extend(
            letters[from as usize..=to as usize]
                .iter()
                .map(u8::to_ascii_uppercase),
        );
    }

    fn label(&self, seq: SeqKey, out: &mut Vec<u8>) {
        out.extend_from_slice(match seq {
            SeqKey::Query => self.query_label.as_bytes(),
            SeqKey::Subject(index) => self.subjects[index as usize].1.as_bytes(),
        });
    }

    fn masks(&self, seq: SeqKey, out: &mut Vec<(u32, u32)>) {
        out.extend_from_slice(match seq {
            SeqKey::Query => &self.query_masks,
            SeqKey::Subject(index) => &self.subject_masks[index as usize],
        });
    }
}

/// The probe of query `query` (`Query_<query_number>`) and the subject records `subjects` (`Subject_N`
/// in this order).
fn probe(query: &str, query_number: usize, subjects: &[&str]) -> Probe {
    Probe {
        query: sequence(query),
        query_label: format!("Query_{query_number}"),
        subjects: subjects
            .iter()
            .enumerate()
            .map(|(index, name)| (sequence(name), format!("Subject_{}", index + 1)))
            .collect(),
        query_masks: Vec::new(),
        subject_masks: vec![Vec::new(); subjects.len()],
    }
}

/// The Dense-seg of an HSP of BTOP `btop` that starts at `qstart` and `sstart` (1-based): one segment per
/// run of aligned, query-only and subject-only columns.
fn push_btop(hsps: &mut Hsps, subject: u32, qstart: u32, sstart: u32, btop: &str) {
    let bytes = btop.as_bytes();
    let mut columns = Vec::new();
    let mut at = 0;
    while at < bytes.len() {
        if bytes[at].is_ascii_digit() {
            let end = at
                + bytes[at..]
                    .iter()
                    .take_while(|b| b.is_ascii_digit())
                    .count();
            let run: usize = btop[at..end].parse().expect("a BTOP run");
            columns.extend(std::iter::repeat_n((true, true), run));
            at = end;
        } else {
            columns.push((bytes[at] != b'-', bytes[at + 1] != b'-'));
            at += 2;
        }
    }
    let (mut q, mut s) = (qstart - 1, sstart - 1);
    let (mut starts, mut lens) = (Vec::new(), Vec::new());
    let mut index = 0;
    while index < columns.len() {
        let kind = columns[index];
        let run = columns[index..]
            .iter()
            .take_while(|&&column| column == kind)
            .count() as u32;
        starts.push(if kind.0 { q as i32 } else { -1 });
        starts.push(if kind.1 { s as i32 } else { -1 });
        lens.push(run as i32);
        if kind.0 {
            q += run;
        }
        if kind.1 {
            s += run;
        }
        index += run as usize;
    }
    hsps.push_dense_seg(subject, &starts, &lens, 0, 0);
}

/// The section of the HSPs `rows` (subject index, qstart, sstart, BTOP) in format `format`.
fn section(
    probe: &Probe,
    rows: &[(u32, u32, u32, &str)],
    format: u8,
    line_length: usize,
) -> String {
    let mut hsps = Hsps::default();
    for &(subject, qstart, sstart, btop) in rows {
        push_btop(&mut hsps, subject, qstart, sstart, btop);
    }
    let view = View {
        identity: matches!(format, 1 | 3),
        anchored: matches!(format, 1 | 2),
    };
    let mut out = Vec::new();
    write_section(&mut out, view, line_length, &hsps, probe).expect("the section");
    String::from_utf8(out).expect("ASCII")
}

